// Reactivos tipo examen — Parte 1 (Arts. 1 a 6 LIEPS)
// Estilo CENEVAL / profesora: base con caso práctico, datos de contexto que
// descartan supuestos ("no se trata de…", "no existe…"), acotación del análisis
// ("para efectos exclusivamente de…") y opciones paralelas con justificación.
// a = índice de la respuesta correcta (0 = a, 1 = b, 2 = c, 3 = d). Las opciones se barajan al mostrarse.
DB.quiz.push(
{ t:"suj", art:"Art. 1, párr. 3 LIEPS",
  q:"Un organismo descentralizado de la administración pública federal adquiere a un fabricante nacional cerveza que destinará a un evento institucional. La ley que lo crea dispone que no causará impuestos federales, por lo que sostiene que no debe soportar el impuesto especial incluido en la contraprestación. El fabricante expidió el comprobante con los requisitos fiscales y la operación no se ubica en algún supuesto de exención. Conforme a la Ley del IEPS, ¿qué tratamiento corresponde al organismo respecto del impuesto?",
  o:["Puede rechazar la traslación, porque la liberación prevista en su ley de creación prevalece sobre el impuesto que causa el enajenante.",
     "Debe aceptar la traslación, porque la Ley obliga a los organismos descentralizados a aceptarla aunque conforme a otras leyes no causen impuestos federales.",
     "Debe aceptar la traslación únicamente si el impuesto le es trasladado en forma expresa y por separado en el comprobante fiscal.",
     "Puede rechazar la traslación sólo si demuestra que los bienes no se destinarán a su reventa ni a la realización de actividades gravadas por las que sea contribuyente."],
  a:1, why:"El art. 1 obliga a la Federación, CDMX, Estados, Municipios, organismos descentralizados o cualquier otra persona a aceptar la traslación del IEPS, aunque por otras leyes no causen impuestos federales o estén exentos.",
  hint:"La ley menciona expresamente a la Federación, Estados, Municipios y organismos descentralizados." },

{ t:"suj", art:"Art. 1, fr. I LIEPS",
  q:"Una persona física que no realiza actividades empresariales introduce al país, por única ocasión y mediante el despacho aduanero correspondiente, cigarros que pretende enajenar posteriormente a terceros. No cuenta con antecedentes de importaciones previas ni con inscripción en algún padrón sectorial. Para efectos exclusivamente de determinar si se ubica como sujeto del impuesto por la introducción de las mercancías, ¿qué conclusión corresponde?",
  o:["No es sujeto, porque el impuesto únicamente recae en las personas morales que fabrican, producen o envasan los bienes gravados en territorio nacional.",
     "No es sujeto, porque la introducción de mercancías sólo genera el impuesto general de importación y el IVA.",
     "Es sujeto, porque la Ley considera importación la introducción al país de bienes y obliga a personas físicas y morales.",
     "Es sujeto únicamente cuando la introducción de los bienes se realiza de manera habitual y con fines comerciales, lo que no ocurre en una importación ocasional."],
  a:2, why:"Son sujetos las personas físicas y morales que enajenen en territorio nacional o importen los bienes señalados en la Ley. Se considera importación la introducción al país de bienes; no se exige habitualidad.",
  hint:"Revisa quiénes están obligados en el primer párrafo del art. 1." },

{ t:"suj", art:"Art. 1, último párrafo LIEPS",
  q:"Un productor enajena un bien gravado cuyo precio se encuentra sujeto a una tarifa oficial fijada por la autoridad competente. Uno de sus clientes, que no es contribuyente del impuesto, argumenta que la incorporación del IEPS al precio implica cobrar una cantidad superior a la autorizada y, en consecuencia, contraviene la tarifa oficial. No existe disposición especial que regule la operación. Conforme a la Ley del IEPS, ¿qué criterio corresponde?",
  o:["El impuesto puede incorporarse, porque la Ley dispone que no se considera violatorio de precios o tarifas, incluyendo los oficiales.",
     "El productor debe absorber el impuesto, porque la tarifa oficial limita el monto total que puede cobrarse al adquirente por cualquier concepto, incluidos los impuestos.",
     "El impuesto sólo puede incorporarse cuando la autoridad que fijó la tarifa lo autorice de manera expresa.",
     "El impuesto debe cobrarse mediante un comprobante distinto, para no alterar el precio oficial del bien."],
  a:0, why:"El art. 1 dispone que el impuesto no se considera violatorio de precios o tarifas, incluyendo los oficiales.",
  hint:"Último párrafo del art. 1." },

{ t:"suj", art:"Art. 1, párr. 2 LIEPS",
  q:"Un contribuyente enajena bienes de distintos incisos de la fracción I del artículo 2o. y observa que algunos de sus productos se cuantifican por unidades de medida, mientras que otros se determinan en función de su valor. No realiza importaciones ni se ubica en supuestos de exención. Conforme a las reglas generales de la Ley, ¿cómo debe calcularse el impuesto?",
  o:["Aplicando una tasa única al precio de venta al público, porque el impuesto grava el consumo final de los bienes.",
     "Aplicando a los valores que señala la Ley la tasa del artículo 2o. o, en su caso, la cuota que la propia Ley establece.",
     "Aplicando una cuota fija por unidad a todos los bienes, porque las tasas se reservan a la prestación de servicios y a las importaciones definitivas.",
     "Aplicando la tasa del IVA más una sobretasa específica, porque el IEPS es un impuesto complementario de aquél."],
  a:1, why:"El impuesto se calcula aplicando a los valores la tasa que para cada bien o servicio establece el art. 2o. o, en su caso, la cuota establecida en la Ley (ad valorem o cuota específica).",
  hint:"Existen dos mecanismos: tasa y cuota." },

// ---- Tasas y cuotas ----
{ t:"tas", art:"Art. 2, fr. I, inc. A) LIEPS",
  q:"Una vinícola enajena a un distribuidor que es contribuyente del impuesto vino de mesa con una graduación alcohólica de 12° G.L., medida a la temperatura que establece la Ley. La operación se realiza en territorio nacional, la contraprestación se cobra efectivamente en el mismo mes y no se ubica en alguno de los supuestos de exención. ¿Qué tasa corresponde a la enajenación?",
  o:["30%, porque los vinos de mesa se ubican en el rango intermedio de graduación por su proceso de fermentación.",
     "53%, porque toda bebida obtenida por fermentación tributa a la tasa máxima del inciso A).",
     "26.5%, porque su graduación alcohólica no excede de 14° G.L.",
     "0%, porque el vino de mesa se considera un producto agrícola sin transformación industrial."],
  a:2, why:"Bebidas con contenido alcohólico y cerveza: hasta 14° G.L. 26.5%; más de 14° y hasta 20° G.L. 30%; más de 20° G.L. 53%.",
  hint:"Ubica 12° en los rangos: hasta 14°, de 14° a 20°, más de 20°." },

{ t:"tas", art:"Art. 2, fr. I, inc. A) LIEPS",
  q:"Un envasador enajena en territorio nacional, dentro del mismo periodo, un licor con graduación de 18° G.L. y un tequila con graduación de 38° G.L., ambos en envases con capacidad inferior a 5,000 mililitros y con los marbetes correspondientes. Ninguna de las operaciones se encuentra exenta ni se trata de exportaciones. ¿Qué tasas corresponden, respectivamente?",
  o:["26.5% y 30%, porque ambas bebidas se ubican en los dos primeros rangos de graduación alcohólica.",
     "30% y 53%, porque el licor excede de 14° sin rebasar 20° G.L., mientras que el tequila excede de 20° G.L.",
     "30% y 50%, porque el tequila, al superar 20° G.L., se asimila al alcohol para efectos de la tasa.",
     "53% en ambos casos, porque se trata de bebidas destiladas y no de bebidas fermentadas."],
  a:1, why:"Más de 14° y hasta 20° G.L.: 30%. Más de 20° G.L.: 53%. El 50% es para alcohol, alcohol desnaturalizado y mieles incristalizables (inciso B).",
  hint:"El 50% pertenece a otro inciso distinto de las bebidas." },

{ t:"tas", art:"Arts. 2, fr. I, inc. B) y 3, fr. VI LIEPS",
  q:"Una destiladora enajena a una empresa industrial una solución acuosa de etanol con graduación de 96° G.L. a 15 °C, que no se destina a uso automotriz. El adquirente la utilizará como insumo de su proceso productivo, y la destiladora no cumple las obligaciones del artículo 19 a las que se condiciona la liberación del pago. ¿Qué tratamiento corresponde a la enajenación?",
  o:["53%, porque su graduación excede de 20° G.L. y se trata de una bebida con contenido alcohólico.",
     "50%, porque se considera alcohol al tener una graduación mayor de 55° G.L. a 15 °C.",
     "No causa el impuesto, porque al destinarse a un proceso industrial no constituye un bien de consumo final.",
     "26.5%, porque al no estar lista para su consumo no se ubica en los rangos superiores de graduación."],
  a:1, why:"Alcohol es la solución acuosa de etanol con graduación mayor de 55° G.L. a 15 °C (sin incluir etanol automotriz). El alcohol, alcohol desnaturalizado y mieles incristalizables tributan al 50%; su exención está condicionada a cumplir el art. 19.",
  hint:"Las bebidas alcohólicas llegan hasta 55° G.L.; arriba de eso cambia la definición." },

{ t:"tas", art:"Art. 2, fr. I, inc. C) y Transitorio 2o. DOF 07-11-2025",
  q:"Un fabricante de cigarros enajena en marzo de 2026, en territorio nacional, 10,000 cigarros a un comerciante detallista. Además de la tasa ad valorem que le corresponde, debe determinar la cuota específica por unidad. El texto del inciso C) señala una cuota de $1.1584 por cigarro, establecida mediante el decreto publicado en noviembre de 2025. No existen otras disposiciones de beneficio aplicables. ¿Qué cuota por cigarro corresponde aplicar en ese ejercicio?",
  o:["$1.1584, porque es la cuota que establece el texto vigente del inciso C) del artículo 2o.",
     "$0.8516, porque el régimen transitorio fija esa cuota para 2026 y la cuota prevista en el artículo entra en vigor hasta 2030.",
     "Ninguna, porque a partir de 2026 los cigarros únicamente causan la tasa del 200%.",
     "$0.6445, porque las cuotas modificadas sólo son aplicables a partir del ejercicio siguiente a su publicación."],
  a:1, why:"La cuota de $1.1584 del segundo párrafo del inciso C) entra en vigor el 1 de enero de 2030. Para 2026 la cuota es $0.8516 (2027: $0.9197; 2028: $0.9932; 2029: $1.0726). La tasa para cigarros es 200%.",
  hint:"Revisa la nota de vigencia y el transitorio segundo de la reforma de noviembre de 2025." },

{ t:"tas", art:"Art. 2, fr. I, inc. C) LIEPS",
  q:"Un productor enajena en territorio nacional puros elaborados enteramente a mano, sin intervención de procesos mecanizados en su manufactura. El adquirente es un comercializador que posteriormente los revenderá al público en general. La operación no corresponde a una exportación. Respecto del productor, ¿qué tratamiento corresponde a la enajenación?",
  o:["200% más la cuota por cigarro equivalente, porque los puros se asimilan a los cigarros para efectos de la cuota.",
     "32%, sin cuota específica, porque la cuota no es aplicable a los puros y otros tabacos labrados hechos enteramente a mano.",
     "32% más la cuota por cada 0.75 gramos, porque la cuota se determina en función del peso total del tabaco, con independencia de la forma en que se elaboró.",
     "Exenta, porque los productos elaborados de manera artesanal no se ubican en el objeto del impuesto."],
  a:1, why:"Puros y otros tabacos labrados hechos enteramente a mano: 32%. La cuota por peso (peso total ÷ 0.75) se aplica a los demás tabacos labrados, con excepción de los hechos enteramente a mano.",
  hint:"La propia Ley exceptúa a los hechos enteramente a mano de la cuota." },

{ t:"tas", art:"Arts. 2, fr. I, inc. C) y 3, fr. VIII, inc. d) LIEPS",
  q:"Una empresa enajena en territorio nacional un producto que contiene nicotina, que no contiene tabaco y que no está diseñado para calentarse ni quemarse. La etiqueta indica el contenido de nicotina en miligramos, y el producto no cuenta con registro sanitario como terapia de reemplazo. ¿Qué tasa corresponde y cómo se determina la base de la cuota específica?",
  o:["200%, y la cuota se aplica al resultado de dividir el peso total del producto entre 0.75.",
     "100%, y la cuota se aplica al resultado de dividir el contenido total de nicotina, expresado en miligramos, entre 8.",
     "32%, sin cuota específica, porque ésta se reserva para los tabacos labrados que contienen hoja de tabaco.",
     "No causa el impuesto, porque al no contener tabaco no se ubica en el inciso C)."],
  a:1, why:"Otros productos que contengan nicotina: 100%. La cuota se aplica al resultado de dividir los miligramos de nicotina entre 8 (se considera que un cigarro contiene 8 mg de nicotina).",
  hint:"Un cigarro equivale a 0.75 g de tabaco y a 8 mg de nicotina." },

{ t:"tas", art:"Art. 2, fr. I, inc. C) LIEPS",
  q:"Un fabricante enajena paquetes de tabaco picado que se consideran otros tabacos labrados no elaborados enteramente a mano. Cada paquete contiene 150 gramos de tabaco mezclado con otras sustancias y se acompaña de papel para enrolar que no contiene tabaco. La operación se realiza en territorio nacional y no está exenta. ¿Cómo se determina la cantidad sobre la cual se aplica la cuota específica?",
  o:["Dividiendo 150 entre 0.75, sin considerar el papel ni el filtro que no contienen tabaco, lo que da como resultado 200 unidades.",
     "Dividiendo 150 entre 8, porque la cuota se determina con base en el contenido de nicotina del producto.",
     "Dividiendo entre 0.75 el peso total del paquete, incluyendo el papel, porque forma parte del bien enajenado.",
     "No se aplica cuota, porque ésta únicamente corresponde a los cigarros y no a otros tabacos labrados."],
  a:0, why:"A otros tabacos labrados se aplica la cuota al resultado de dividir su peso total entre 0.75 (incluye otras sustancias mezcladas con el tabaco), sin considerar filtro, papel u otra sustancia sin tabaco con que estén envueltos.",
  hint:"0.75 es el peso en gramos de un cigarro." },

{ t:"tas", art:"Art. 2, fr. I, inc. D) LIEPS",
  q:"Un importador enajena a una estación de servicio 1,000.5 litros de gasolina con 92 octanos, en una operación que no se ubica en algún supuesto de exención. Al determinar el impuesto del inciso D) de la fracción I del artículo 2o., el contribuyente duda tanto de la cuota aplicable como del tratamiento que debe darse a la fracción de litro. ¿Qué procede?",
  o:["Aplicar la cuota de la gasolina menor a 91 octanos, porque es la más baja y debe aplicarse la más favorable.",
     "Aplicar la cuota de la gasolina mayor o igual a 91 octanos y, a la fracción de litro, la proporción que le corresponda.",
     "Redondear a 1,001 litros, porque la cuota sólo puede aplicarse a unidades completas de medida, sin considerar las fracciones de litro enajenadas.",
     "Aplicar una tasa sobre la contraprestación, porque los combustibles enajenados por importadores tributan ad valorem."],
  a:1, why:"Gasolina ≥ 91 octanos tiene su propia cuota por litro (5.6579 en 2026). Tratándose de fracciones de unidad de medida, la cuota se aplica en la proporción correspondiente.",
  hint:"Los combustibles automotrices tributan por cuota, no por tasa." },

{ t:"tas", art:"Art. 2, fr. I, incs. F) y G) LIEPS",
  q:"Un fabricante enajena en territorio nacional una bebida que contiene una mezcla de cafeína y taurina, lo que la ubica como bebida energetizante. Adicionalmente, conforme a la información de su etiqueta, la fórmula contiene azúcares añadidos. La operación no se realiza en restaurantes ni en otros lugares donde se proporcionen alimentos y bebidas. ¿Qué impuesto corresponde a la enajenación?",
  o:["Únicamente el 25%, porque la clasificación como energetizante desplaza la aplicación de cualquier otro inciso.",
     "Únicamente la cuota por litro de bebidas saborizadas, porque el contenido de azúcares añadidos es la característica que define el gravamen y excluye la aplicación del inciso F).",
     "El 25% y, adicionalmente, la cuota por litro de bebidas saborizadas, porque el inciso G) también se aplica a los bienes del inciso F).",
     "Ninguno, porque al tratarse de una bebida no alcohólica únicamente se encuentra sujeta al IVA."],
  a:2, why:"El inciso G) también es aplicable a los bienes del inciso F) cuando contengan azúcares o edulcorantes añadidos, en adición al 25% del inciso F).",
  hint:"El inciso G) dice que se aplica \"en adición\" al inciso F)." },

{ t:"tas", art:"Art. 2, fr. I, inc. G) LIEPS",
  q:"Una empresa refresquera enajena 1,000 litros de una bebida saborizada que, conforme a su etiqueta, no contiene azúcares añadidos, pero sí edulcorantes añadidos. La bebida no cuenta con registro sanitario como medicamento ni se enajena en restaurantes, bares u otros lugares de consumo. ¿Qué cuota corresponde aplicar a partir de 2026?",
  o:["$3.0818 por litro, porque todas las bebidas saborizadas se gravan con la misma cuota, con independencia de que contengan azúcares o edulcorantes añadidos.",
     "$1.5000 por litro, porque la Ley establece una cuota específica para las bebidas con edulcorantes añadidos.",
     "Ninguna, porque el impuesto únicamente grava las bebidas que contienen azúcares añadidos.",
     "8% sobre el valor, porque se considera un alimento no básico con alta densidad calórica."],
  a:1, why:"Desde 2026: $3.0818 por litro con azúcares añadidos y $1.5000 por litro con edulcorantes añadidos.",
  hint:"La Ley distingue entre azúcares y edulcorantes." },

{ t:"tas", art:"Arts. 2, fr. I, inc. G) y 11 LIEPS",
  q:"Una empresa enajena sobres de polvo que, conforme a las especificaciones del fabricante, permiten preparar bebida saborizada con azúcares añadidos al diluirse en agua. El adquirente es un comercializador que los revenderá al público, y el contribuyente desconoce cuántos litros prepararán efectivamente los consumidores finales. ¿Cómo se determina el impuesto?",
  o:["Sobre el peso en kilogramos del polvo enajenado, porque el bien no se enajena en forma líquida.",
     "Considerando el número de litros de bebidas saborizadas que, conforme a las especificaciones del fabricante, se puedan obtener del producto.",
     "A la tasa del 8%, porque los polvos para preparar bebidas se consideran alimentos no básicos.",
     "No se causa el impuesto sino hasta que el consumidor final prepara la bebida, porque antes no existe el bien gravado."],
  a:1, why:"Para concentrados, polvos, jarabes, esencias o extractos de sabores, el impuesto se calcula tomando en cuenta el número de litros de bebidas saborizadas que se puedan obtener según las especificaciones del fabricante.",
  hint:"Piensa en el resultado final: litros de bebida." },

{ t:"tas", art:"Art. 2, fr. I, inc. H) LIEPS",
  q:"Una empresa importa coque de petróleo que destinará a un proceso de combustión en su planta, sin que exista algún supuesto que la libere del pago. Al revisar la tabla del inciso H), observa que los combustibles fósiles se expresan en distintas unidades de medida según el tipo de producto. ¿En qué unidad se expresa la cuota aplicable a dicho bien?",
  o:["En centavos por litro, porque todos los combustibles fósiles se cuantifican por su volumen.",
     "En pesos por tonelada, porque así se establece para el coque de petróleo, el coque de carbón y el carbón mineral.",
     "En pesos por tonelada de carbono que contenga, porque se trata de un combustible sólido distinto de los derivados líquidos del petróleo.",
     "En un porcentaje sobre el valor en aduana, porque la operación constituye una importación."],
  a:1, why:"En el inciso H): propano, butano, gasolinas, turbosina, diésel y combustóleo en centavos por litro; coque de petróleo, coque de carbón y carbón mineral en pesos por tonelada; otros combustibles fósiles en pesos por tonelada de carbono.",
  hint:"Los combustibles sólidos se miden por peso." },

{ t:"tas", art:"Arts. 2, fr. I, inc. I) y 8, fr. I, inc. h) LIEPS",
  q:"Un fabricante enajena en territorio nacional dos plaguicidas: el primero clasificado en la categoría 3 de toxicidad aguda y el segundo en la categoría 5, conforme a la norma oficial mexicana aplicable. Ambos se venden al mismo distribuidor y se cobran en el mismo mes. ¿Qué tratamiento corresponde a cada uno?",
  o:["7% para el de categoría 3, mientras que el de categoría 5 no paga el impuesto conforme a la Ley.",
     "9% para ambos, porque se trata de plaguicidas destinados al mismo uso agrícola y enajenados al mismo distribuidor.",
     "6% para el de categoría 3 y 7% para el de categoría 5, porque la tasa aumenta conforme disminuye la toxicidad aguda del producto.",
     "Ambos exentos, porque se consideran insumos de la actividad agropecuaria."],
  a:0, why:"Categorías 1 y 2: 9%; categoría 3: 7%; categoría 4: 6%. Los plaguicidas de categoría 5 no pagan el impuesto (art. 8, fr. I, inc. h).",
  hint:"A mayor toxicidad, mayor tasa; la menor toxicidad (5) queda fuera." },

{ t:"tas", art:"Art. 2, fr. I, inc. J) LIEPS",
  q:"Un productor enajena chocolates que no cuentan con etiquetado nutrimental, por lo que no es posible conocer su densidad calórica a partir del producto. Durante una revisión, el contribuyente no aporta elemento alguno que demuestre su contenido calórico real. No se trata de una exportación ni de una enajenación exenta. ¿Qué tratamiento corresponde?",
  o:["No causa el impuesto, porque la autoridad debe acreditar que la densidad calórica es de 275 kilocalorías o más.",
     "Se presume, salvo prueba en contrario, una densidad de 275 kilocalorías o más por cada 100 gramos, por lo que se gravan al 8%.",
     "Se gravan al 8% únicamente si la autoridad determina la densidad calórica mediante un análisis de laboratorio, porque la carga de la prueba le corresponde.",
     "Se gravan al 25%, porque los productos de confitería se asimilan a las bebidas energetizantes."],
  a:1, why:"Alimentos no básicos con 275 kcal o más por cada 100 g: 8%. Si no tienen etiqueta, se presume, salvo prueba en contrario, que su densidad calórica es igual o superior a 275 kcal/100 g.",
  hint:"La Ley establece una presunción cuando no hay etiqueta." },

{ t:"tas", art:"Art. 2, fr. I, inc. K) LIEPS",
  q:"Una empresa importa videojuegos en formato físico cuyo contenido ha sido clasificado como violento, extremo y para adultos. Posteriormente los enajena al público en general en sus tiendas, expidiendo comprobantes simplificados. Para analizar exclusivamente el tratamiento del IEPS en ambos momentos, ¿qué conclusión corresponde?",
  o:["Causa el 8% tanto en la importación como en la enajenación, porque se trata del mismo bien gravado.",
     "No causa el impuesto en la importación, pero la enajenación al público en general se grava al 8%, porque la Ley excluye expresamente la importación.",
     "Únicamente causa el impuesto en la importación, porque la enajenación posterior constituye una reventa.",
     "No causa el impuesto en ningún momento, porque se trata de un bien de entretenimiento y no de consumo."],
  a:1, why:"El inciso K) grava al 8% los videojuegos violentos, extremos o para adulto en formato físico cuando la enajenación se efectúe al público en general, y aclara que no es aplicable a su importación.",
  hint:"El inciso K) excluye expresamente un acto." },

{ t:"tas", art:"Art. 2, fr. II, inc. A) y art. 8 LIEPS",
  q:"Una persona física presta servicios de comisión a un fabricante de cerveza, interviniendo en la venta del producto en territorio nacional a cambio de una contraprestación por cada operación concretada. Las enajenaciones en las que interviene no se ubican en alguno de los supuestos de exención del artículo 8o. ¿Qué tasa corresponde a la contraprestación del comisionista?",
  o:["3%, porque la comisión se considera un servicio de intermediación de carácter general, distinto de la enajenación del bien en que interviene.",
     "La misma tasa que corresponda a la enajenación de la cerveza, porque la Ley vincula la tasa de estos servicios a la del bien.",
     "0%, porque el comisionista no enajena el bien y, por tanto, no realiza un acto gravado, sino únicamente un servicio accesorio a la enajenación.",
     "16%, porque sobre la comisión únicamente se causa el impuesto al valor agregado."],
  a:1, why:"En comisión, mediación, agencia, representación, correduría, consignación y distribución de los bienes de los incisos A), B), C), F), I) y J), la tasa es la que corresponda a la enajenación del bien. No se paga si la enajenación está exenta conforme al art. 8.",
  hint:"El servicio sigue la tasa del bien que se vende." },

{ t:"tas", art:"Art. 2, fr. II, inc. B) LIEPS",
  q:"Una sociedad con permiso vigente otorgado conforme a la Ley Federal de Juegos y Sorteos realiza en territorio nacional juegos con apuestas en un establecimiento abierto al público. Durante el mes obtiene ingresos por las apuestas captadas, sin que se trate de sorteos gratuitos ni de supuestos de exención. ¿Qué tasa del impuesto corresponde a partir de 2026?",
  o:["30%, porque es la tasa que se aplicaba a los juegos con apuestas antes de la reforma de 2025.",
     "50%, porque la Ley establece esa tasa para la realización de juegos con apuestas y sorteos.",
     "3%, porque se trata de un servicio de entretenimiento asimilable a los de telecomunicaciones.",
     "No causa el impuesto, porque la sociedad cuenta con el permiso que exige la legislación de la materia."],
  a:1, why:"Desde 2026, la realización de juegos con apuestas y sorteos que requieran permiso conforme a la Ley Federal de Juegos y Sorteos se grava al 50%.",
  hint:"Reforma 2026: la tasa subió considerablemente." },

{ t:"tas", art:"Art. 2, fr. II, inc. C) LIEPS",
  q:"Una empresa proporciona en territorio nacional servicios a través de redes públicas de telecomunicaciones, distintos de la telefonía fija rural, la telefonía pública, la interconexión y el acceso a internet. Los servicios se cobran mensualmente a usuarios residentes en el país. ¿Qué tasa del impuesto corresponde?",
  o:["3%, porque es la tasa establecida para los servicios proporcionados a través de redes públicas de telecomunicaciones.",
     "8%, porque estos servicios se asimilan a los servicios digitales de entretenimiento cuando se prestan de forma continua mediante una red pública.",
     "16%, porque estos servicios únicamente causan el impuesto al valor agregado.",
     "0%, porque se trata de servicios de interés público prestados mediante concesión."],
  a:0, why:"Los servicios proporcionados en territorio nacional a través de una o más redes públicas de telecomunicaciones se gravan al 3% (con las exenciones del art. 8, fr. IV).",
  hint:"Es la tasa más baja del art. 2." },

{ t:"tas", art:"Art. 2, fr. II, inc. D) LIEPS",
  q:"Una plataforma cobra una suscripción mensual que otorga acceso a un catálogo de videojuegos, algunos de ellos clasificados como violentos y para adultos. En el comprobante fiscal no se separa el precio que corresponde a cada videojuego ni a los títulos gravados. La plataforma no realiza otras actividades gravadas. ¿Cómo se determina la base del impuesto?",
  o:["No se causa el impuesto, porque la suscripción da acceso a un catálogo y no a un videojuego en particular.",
     "Se aplica el 8% al total de la suscripción, porque basta con que el catálogo contenga un título gravado para que toda la contraprestación quede sujeta al impuesto.",
     "Se entiende que el 70% de la contraprestación corresponde a los servicios gravados, sin ser menor al monto que correspondería por separado.",
     "Se aplica el 3%, porque el servicio se proporciona a través de redes públicas de telecomunicaciones."],
  a:2, why:"Si no se separa en el comprobante el precio de cada videojuego, la contraprestación se entiende en un 70% correspondiente a los servicios del inciso D) (tasa 8%), sin ser menor al que corresponda al servicio pagado por separado.",
  hint:"Ojo con el porcentaje que la Ley presume." },

{ t:"tas", art:"Art. 2, fr. II, inc. D) LIEPS",
  q:"Un videojuego clasificado como violento se descarga sin costo alguno; sin embargo, dentro del mismo se ofrecen armas, niveles y contenido adicional mediante pago. El desarrollador es residente en México, no existe una suscripción y los pagos se realizan directamente en la aplicación. ¿Cómo se grava esta operación?",
  o:["No causa el impuesto, porque el acceso y la descarga del videojuego son gratuitos.",
     "Se aplica el 8% sobre el precio pagado por el contenido adicional, porque la Ley comprende los videojuegos sin pago por acceso o descarga.",
     "Se aplica el 8% sobre un valor de mercado estimado del videojuego descargado.",
     "Se aplica el 3%, porque se trata de un servicio digital prestado a través de internet."],
  a:1, why:"Quedan comprendidos los videojuegos sin pago por acceso o descarga que ofertan contenido adicional; la tasa se aplica sobre el precio pagado por el contenido adicional.",
  hint:"Lo que se paga dentro del juego es lo gravado." },

{ t:"tas", art:"Art. 2, fr. III LIEPS",
  q:"Un fabricante residente en México exporta en definitiva botanas con densidad calórica superior a 275 kilocalorías por cada 100 gramos. Para su elaboración adquirió insumos por los que le fue trasladado el impuesto. La exportación se realiza conforme a la legislación aduanera y el fabricante está inscrito en los padrones correspondientes. ¿Qué tratamiento corresponde a la exportación?",
  o:["Está exenta, sin derecho a acreditar el impuesto trasladado por los insumos utilizados, porque la exportación es un acto liberado del pago.",
     "Se grava a la tasa del 0%, con los mismos efectos que los actos gravados, por lo que el exportador se considera contribuyente.",
     "Se grava al 8%, porque el bien fue elaborado en territorio nacional.",
     "No es objeto del impuesto, porque el consumo de los bienes se realiza fuera del país y la Ley sólo grava el consumo en territorio nacional."],
  a:1, why:"La exportación definitiva de alimentos no básicos (inciso J) por fabricantes que usaron insumos gravados se grava al 0%. Produce los mismos efectos que los actos gravados y el exportador se considera contribuyente.",
  hint:"Tasa 0% ≠ exención." },

{ t:"tas", art:"Art. 2o.-A LIEPS",
  q:"Una empresa enajena gasolina en territorio nacional y, además de las cuotas del inciso D), causa las cuotas del artículo 2o.-A cuyo producto se destina a las entidades federativas y municipios. Su cliente, que es contribuyente del impuesto, le solicita que estas cuotas aparezcan en forma expresa y por separado en el comprobante. ¿Cómo deben trasladarse las cuotas del artículo 2o.-A?",
  o:["En forma expresa y por separado, porque el adquirente es contribuyente del impuesto y así lo solicita para efectos de su acreditamiento.",
     "Incluidas en el precio, sin trasladarlas en ningún caso en forma expresa y por separado, y sin que computen para el cálculo del IVA.",
     "No se trasladan, porque son absorbidas por el enajenante en su calidad de contribuyente.",
     "Incluidas en el precio, formando parte de la base para el cálculo del impuesto al valor agregado, porque integran el valor del bien enajenado."],
  a:1, why:"El art. 2o.-A dispone que el monto se traslada en el precio, en ningún caso en forma expresa y por separado, y que estas cuotas no computan para el cálculo del IVA. Lo recaudado se destina a entidades y municipios.",
  hint:"Estas cuotas son las que se reparten a entidades federativas." },

{ t:"tas", art:"Art. 2o.-E LIEPS",
  q:"Una empresa enajena asfaltos derivados del petróleo que serán utilizados por su cliente para la pavimentación de carreteras. La autoridad revisa si dichos productos deben tributar como \"otros combustibles fósiles\" del inciso H), al tratarse de derivados de hidrocarburos. No existe controversia sobre su composición. ¿Qué criterio corresponde?",
  o:["Deben tributar como otros combustibles fósiles, porque derivan del petróleo y la Ley grava a todos los derivados de hidrocarburos.",
     "No se consideran otros combustibles fósiles, porque no se destinan a un proceso de combustión.",
     "Se consideran combustibles fósiles únicamente si su densidad excede de un kilogramo por litro, porque así se distinguen de los combustibles líquidos.",
     "Sólo tributan como combustibles fósiles cuando son introducidos al país mediante importación."],
  a:1, why:"El art. 2o.-E excluye de \"otros combustibles fósiles\" a parafinas, materia prima para negro de humo, residuo largo, asfaltos, aceite cíclico ligero, aceites básicos, lubricantes y propileno, porque no se destinan a combustión.",
  hint:"La clave es el destino: combustión." },

// ---- Definiciones ----
{ t:"def", art:"Art. 3, fr. I, inc. a) LIEPS",
  q:"Un productor elabora una bebida fermentada de frutas que, medida a la temperatura de 15 °C, presenta una graduación alcohólica de 2.5° G.L. Pretende enajenarla en territorio nacional y consulta si debe aplicar alguna de las tasas del inciso A). Para efectos exclusivamente de la definición legal, ¿cómo se clasifica la bebida?",
  o:["Como bebida alcohólica, porque contiene alcohol etílico en cualquier proporción.",
     "No se considera bebida alcohólica, porque éstas son las que tienen más de 3° G.L. y hasta 55° G.L. a 15 °C.",
     "Como bebida refrescante, porque su graduación es inferior a la de la cerveza.",
     "No se considera bebida alcohólica, porque únicamente la cerveza puede obtenerse por fermentación para efectos de la Ley."],
  a:1, why:"Bebidas alcohólicas: las que a 15 °C tengan una graduación de más de 3° G.L. y hasta 55° G.L., incluyendo aguardiente y concentrados aunque tengan mayor graduación.",
  hint:"Rango: más de 3° hasta 55°." },

{ t:"def", art:"Art. 3, frs. III, IV y V LIEPS",
  q:"Un productor envasa bebidas alcohólicas en recipientes de 20 litros para trasladarlas de su planta a la de un envasador. Las bebidas no se enajenarán al público en esa presentación, y el traslado se realizará en un vehículo de su propiedad. ¿Qué signo de control fiscal corresponde adherir?",
  o:["Marbete, porque toda bebida alcohólica debe portarlo con independencia de su presentación.",
     "Precinto, porque se trata de bebidas a granel en recipientes de más de 5,000 mililitros que se encuentran en transporte.",
     "Ninguno, porque las bebidas no se enajenarán al público en general en esa presentación.",
     "Código de seguridad impreso, porque se trata de un traslado entre plantas del mismo contribuyente."],
  a:1, why:"Bebidas a granel son las envasadas en recipientes de más de 5,000 ml. El marbete es para envases de hasta 5,000 ml; el precinto para recipientes que excedan 5,000 ml (se adhiere en tránsito o transporte, art. 19 fr. V).",
  hint:"El límite es 5,000 mililitros." },

{ t:"def", art:"Art. 3, fr. XII LIEPS",
  q:"Un fabricante de bebidas alcohólicas enajena mercancía a un distribuidor. Por el incumplimiento en el plazo de pago, cobra además del precio pactado intereses moratorios y una pena convencional; asimismo, carga al adquirente el importe de los envases no retornables. Todos los conceptos se cobran efectivamente en el mismo mes y están expresados sin impuestos. ¿Qué conceptos integran la contraprestación?",
  o:["Únicamente el precio de las bebidas, porque los demás conceptos tienen naturaleza accesoria.",
     "El precio y los envases, excluyendo los intereses y la pena convencional por su naturaleza financiera e indemnizatoria, y no de contraprestación.",
     "El precio, los intereses moratorios, la pena convencional y los envases no retornables, porque son cantidades cargadas al adquirente.",
     "El precio y la pena convencional, excluyendo los intereses moratorios, porque éstos corresponden únicamente al retraso en el pago."],
  a:2, why:"Contraprestación: precio pactado más intereses normales o moratorios, penas convencionales o cualquier otro concepto distinto de impuestos; también anticipos, publicidad convenida y envases y empaques no retornables.",
  hint:"Todo lo que se carga al adquirente, salvo impuestos." },

{ t:"def", art:"Art. 3, fr. XII LIEPS",
  q:"Dos empresas intercambian bebidas alcohólicas por tabacos labrados, cuya enajenación está gravada. La operación se perfecciona sin que exista pago en efectivo entre ellas, y se cuenta con el valor de mercado de ambos bienes. Ninguna de las empresas entrega dinero a la otra como compensación. ¿Qué criterio corresponde conforme a la Ley del IEPS?",
  o:["No se causa el impuesto, porque no existe una contraprestación pactada en dinero.",
     "Se causa el impuesto sólo por la diferencia entre los valores de los bienes intercambiados, porque únicamente ese excedente representa una contraprestación.",
     "Se paga el impuesto por cada bien cuya propiedad se transmita, tomando su valor de mercado o, en su defecto, el de avalúo.",
     "Se causa el impuesto únicamente por el bien que tenga el mayor valor de mercado."],
  a:2, why:"En permutas y pagos en especie, el IEPS se paga por cada bien cuya propiedad se transmita; el valor es el de mercado o, en su defecto, de avalúo.",
  hint:"Igual que en IVA: cada bien transmitido." },

{ t:"def", art:"Art. 3, fr. XII LIEPS",
  q:"Un fabricante de cerveza recibe de un cliente un depósito antes de entregar la mercancía. En el contrato, el depósito se denomina \"garantía de abastecimiento\" y se aplicará al precio cuando se efectúe la entrega. No existe pacto de devolución distinto. ¿Qué tratamiento corresponde al depósito para efectos de la contraprestación?",
  o:["No forma parte de la contraprestación, porque el bien todavía no ha sido entregado al adquirente.",
     "Forma parte de la contraprestación, porque los anticipos o depósitos se incluyen cualquiera que sea el nombre que se les dé.",
     "Forma parte de la contraprestación sólo si excede del 50% del precio pactado, porque de lo contrario se considera una garantía y no un pago.",
     "Únicamente forma parte de la contraprestación si se documenta en un comprobante fiscal distinto."],
  a:1, why:"También forman parte de la contraprestación los anticipos o depósitos recibidos antes de entregar el bien o prestar el servicio, cualquiera que sea el nombre que se les dé.",
  hint:"El nombre que se le dé no importa." },

{ t:"def", art:"Arts. 3, fr. I, inc. b) y 4, fr. IV LIEPS",
  q:"Un productor elabora una bebida a base de vino de mesa, al que adiciona agua, gas y jugo de frutas, y consulta cómo se clasifica para efectos de la Ley, ya que de ello depende la clase de bienes contra la que podrá acreditar el impuesto. ¿Qué se entiende por bebida refrescante?",
  o:["Cualquier bebida no alcohólica que contenga gas carbónico añadido, porque la Ley la distingue de las bebidas saborizadas y de las energetizantes.",
     "La elaborada con un mínimo de 50% a base de vino de mesa, con aditivos como agua, gas o jugo, o la elaborada de destilados alcohólicos diversos.",
     "La cerveza con una graduación alcohólica inferior a 3° G.L.",
     "La bebida energetizante que contenga vino de mesa en cualquier proporción, porque la combinación de ambos productos genera una clase distinta de bienes."],
  a:1, why:"Bebidas refrescantes: elaboradas con mínimo 50% de vino de mesa, más los aditivos permitidos, o elaboradas de destilados alcohólicos diversos. Para acreditamiento se consideran de clase diferente a las demás bebidas alcohólicas.",
  hint:"La base es el vino de mesa." },

{ t:"def", art:"Art. 3, fr. XXXVII y art. 19, fr. XXIV LIEPS",
  q:"Un bar abre botellas de bebidas alcohólicas para venderlas por copeo a sus clientes, quienes las consumen dentro del mismo establecimiento. El bar no es fabricante, productor, envasador ni importador de dichas bebidas. Respecto del marbete de las botellas que abre, ¿qué obligación específica tiene?",
  o:["Ninguna, porque la venta por copeo no se considera enajenación y, por tanto, el bar no tiene obligaciones respecto del impuesto especial.",
     "Realizar, en presencia del consumidor, la lectura del código QR del marbete mediante un dispositivo móvil.",
     "Retirar el marbete y devolverlo a la autoridad una vez agotado el contenido de la botella.",
     "Adherir un precinto a cada botella abierta para su control durante el consumo."],
  a:1, why:"Los establecimientos de consumo final (bares, cantinas, restaurantes, etc.) deben realizar en presencia del consumidor la lectura con dispositivo móvil del código QR del marbete.",
  hint:"Es una obligación tecnológica frente al cliente." },

// ---- Acreditamiento ----
{ t:"acr", art:"Art. 4 LIEPS",
  q:"Un distribuidor adquiere bebidas alcohólicas a un fabricante, quien le traslada el impuesto en forma expresa y por separado en el comprobante. El distribuidor es contribuyente por la enajenación de esos bienes, los revende sin modificar su estado, forma o composición, y ya pagó la totalidad de la contraprestación. ¿Puede acreditar el impuesto trasladado?",
  o:["No, porque en el IEPS no procede el acreditamiento del impuesto trasladado por los proveedores.",
     "Sí, porque cumple los requisitos de la Ley, entre ellos el traslado expreso, la misma clase de bienes y el pago efectivo.",
     "Sí, y puede hacerlo contra cualquier IEPS a su cargo, aun cuando derive de otra clase de bienes, porque se trata del mismo impuesto federal.",
     "Sólo si el fabricante le otorga una autorización expresa para efectuar el acreditamiento."],
  a:1, why:"Requisitos del art. 4: ser contribuyente por el bien; enajenar sin modificar estado, forma o composición (salvo excepciones); traslado expreso y por separado en comprobante; misma clase de bienes (mismo inciso); y que haya sido efectivamente pagado.",
  hint:"Son cinco requisitos; uno de ellos es \"misma clase\"." },

{ t:"acr", art:"Arts. 4, párr. 2 y 11 LIEPS",
  q:"Un comerciante adquiere cigarros a un productor nacional y posteriormente los revende a tiendas detallistas. El comerciante desea acreditar el impuesto que el productor incluyó en el precio contra el que, considera, causa por la reventa. No se trata de cigarros importados por él. ¿Qué criterio corresponde?",
  o:["Puede acreditar el impuesto de la compra contra el de la venta, porque se trata de la misma clase de bienes.",
     "El impuesto no se paga en las enajenaciones subsecuentes de cigarros y, en consecuencia, no procede su acreditamiento ni su devolución.",
     "Debe pagar el impuesto únicamente sobre su margen de utilidad en la reventa.",
     "Debe pagar el impuesto sobre el precio total de reventa, sin derecho a acreditamiento."],
  a:1, why:"Los cigarros (inciso C) no están en la lista de bienes con acreditamiento por traslado. El productor paga sobre el precio de venta al detallista y el impuesto no se paga en las enajenaciones subsecuentes, sin acreditamiento ni devolución.",
  hint:"El inciso C) sólo es acreditable cuando se pagó en la importación." },

{ t:"acr", art:"Art. 4, fr. IV LIEPS",
  q:"Una empresa tiene impuesto trasladado por la adquisición de cerveza y, en el mismo mes, causa impuesto por la enajenación de tequila. Ambos bienes se ubican en el inciso A) de la fracción I del artículo 2o., y la empresa cumple los demás requisitos del acreditamiento. ¿Puede acreditar uno contra el otro?",
  o:["Sí, porque ambos bienes pertenecen al inciso A) de la fracción I del artículo 2o. y, por tanto, se consideran de la misma clase para el acreditamiento.",
     "No, porque la cerveza y las bebidas refrescantes se consideran de clase diferente de las demás bebidas con contenido alcohólico.",
     "Sí, siempre que las tasas aplicables a ambos bienes sean iguales.",
     "Sólo si ambos bienes fueron adquiridos al mismo proveedor."],
  a:1, why:"Los bienes de la misma clase son los agrupados en cada inciso de la fr. I del art. 2, pero la cerveza y las bebidas refrescantes se consideran, cada una, de clase diferente de las demás bebidas con contenido alcohólico.",
  hint:"Hay una excepción expresa dentro del inciso A)." },

{ t:"acr", art:"Art. 4, penúltimo párrafo LIEPS",
  q:"En mayo, un contribuyente tenía derecho a acreditar $50,000 de impuesto trasladado por la adquisición de bienes de la misma clase; sin embargo, por un error administrativo no lo acreditó en mayo, junio ni julio, pese a que tuvo impuesto a cargo suficiente en esos meses. ¿Qué consecuencia jurídica se produce?",
  o:["Puede acreditarlo en cualquier mes posterior, dentro del plazo general de cinco años, porque el derecho se extingue únicamente por prescripción.",
     "Pierde el derecho a acreditarlo en los meses siguientes hasta por la cantidad que pudo haber acreditado.",
     "Debe solicitar su devolución, porque ya no es posible acreditarlo.",
     "Puede acreditarlo en la declaración anual del ejercicio."],
  a:1, why:"Si no se acredita el impuesto trasladado en el mes de que se trate o en los dos meses siguientes, pudiendo haberlo hecho, se pierde el derecho a hacerlo en los meses siguientes hasta por la cantidad que pudo acreditarse.",
  hint:"El mes más dos meses siguientes." },

{ t:"acr", art:"Art. 4, último párrafo LIEPS",
  q:"Una sociedad mercantil cuenta con impuesto acreditable pendiente de aplicar y pretende cederlo, mediante un contrato de cesión de derechos, a otra sociedad del mismo grupo que sí tiene impuesto a cargo. Entre ambas sociedades no existe ni se proyecta una fusión. ¿Es procedente la cesión?",
  o:["Sí, porque ambas sociedades son contribuyentes del impuesto y pertenecen al mismo grupo, por lo que el acreditamiento no sale del grupo económico.",
     "No, porque el derecho al acreditamiento es personal y no se transmite por acto entre vivos, salvo en la fusión de sociedades mercantiles.",
     "Sí, mediante el endoso de los comprobantes fiscales que amparan el impuesto.",
     "Sí, siempre que la autoridad fiscal autorice previamente la cesión."],
  a:1, why:"El derecho al acreditamiento es personal y no puede transmitirse por acto entre vivos, excepto en fusión de sociedades mercantiles.",
  hint:"Sólo una forma de reorganización lo permite." },

{ t:"acr", art:"Art. 4, fr. II LIEPS",
  q:"Un contribuyente adquiere tequila a granel, con el impuesto trasladado en forma expresa y por separado, y lo envasa en botellas de 750 mililitros para enajenarlo. La autoridad sostiene que, al modificar la presentación del bien, perdió el derecho al acreditamiento. ¿Qué criterio corresponde?",
  o:["Pierde el derecho, porque modificó el estado, forma o composición del bien adquirido, requisito que la Ley exige sin excepción para todas las bebidas.",
     "Conserva el derecho, porque la Ley exceptúa a las bebidas alcohólicas a granel del requisito de no modificar su estado, forma o composición.",
     "Conserva el derecho únicamente si enajena las botellas a granel.",
     "Conserva el derecho sólo si el tequila envasado se destina a la exportación."],
  a:1, why:"El requisito de enajenar sin modificar estado, forma o composición no aplica a bebidas alcohólicas a granel o sus concentrados, concentrados para bebidas saborizadas, ni a los bienes de los incisos D), H), I) y J).",
  hint:"Revisa las excepciones de la fracción II del art. 4." },

{ t:"acr", art:"Art. 4 LIEPS",
  q:"Un proveedor que no estaba obligado a trasladar el impuesto lo incluyó en forma expresa y por separado en el comprobante expedido a su cliente, quien lo pagó en su totalidad. El cliente pretende acreditarlo contra el impuesto a su cargo del mismo mes. ¿Qué procede?",
  o:["Puede acreditarlo, porque el impuesto consta expresamente en el comprobante fiscal.",
     "No puede acreditarlo, porque no se considera acreditable el impuesto que se traslade sin tener esa obligación.",
     "Puede acreditarlo, porque lo pagó efectivamente al proveedor y el comprobante reúne los requisitos fiscales que exige el Código Fiscal de la Federación.",
     "Puede acreditarlo, siempre que el proveedor lo haya enterado a la autoridad."],
  a:1, why:"Traslado es el cobro o cargo que el contribuyente debe efectuar. No es acreditable el impuesto que se traslade sin tener esta obligación. Tampoco procede respecto de actos exentos.",
  hint:"Sólo cuenta el traslado obligatorio." },

// ---- Pago, saldos, retenciones ----
{ t:"pag", art:"Art. 5 LIEPS",
  q:"Un fabricante de bebidas alcohólicas causa el impuesto por las enajenaciones cuyas contraprestaciones cobró efectivamente en octubre. No realizó importaciones en ese mes ni tiene saldos a favor pendientes de aplicar. ¿Cuándo y con qué carácter debe efectuar el pago?",
  o:["Mediante pago provisional, a más tardar el 17 de noviembre, a cuenta del impuesto del ejercicio.",
     "Mediante pago mensual definitivo, a más tardar el día 17 de noviembre.",
     "En la declaración anual, que se presenta en marzo del año siguiente.",
     "Mediante pago bimestral, a más tardar el 17 de diciembre."],
  a:1, why:"El IEPS se calcula mensualmente y se paga a más tardar el día 17 del mes siguiente; los pagos mensuales tienen el carácter de definitivos (en importaciones se aplican los arts. 15 y 16).",
  hint:"El IEPS no tiene declaración anual." },

{ t:"pag", art:"Art. 5 LIEPS",
  q:"Un contribuyente obtiene saldo a favor en el impuesto por la enajenación de bebidas alcohólicas y, en el mismo mes, tiene impuesto a cargo por la enajenación de bebidas saborizadas. No realiza exportaciones. Pretende aplicar el saldo a favor contra el impuesto a cargo. ¿Qué procede?",
  o:["Puede compensarlo contra cualquier IEPS a su cargo, porque se trata del mismo impuesto federal y la Ley no distingue entre los bienes que lo originan.",
     "Sólo puede compensarlo contra el impuesto de la misma categoría en los pagos siguientes, porque cada inciso se considera un impuesto distinto.",
     "Puede compensarlo contra el ISR o el IVA a su cargo.",
     "Debe solicitar su devolución inmediata."],
  a:1, why:"El saldo a favor sólo se compensa contra el mismo impuesto a cargo en los pagos mensuales siguientes. Se consideran impuestos distintos cada uno de los gravámenes de los incisos de las frs. I y II del art. 2 y el del art. 2o.-A.",
  hint:"Cada inciso es como un impuesto diferente." },

{ t:"pag", art:"Art. 5 LIEPS",
  q:"Un exportador de alimentos no básicos gravados a la tasa del 0% conforme a la fracción III del artículo 2o. obtiene saldo a favor en el mes. El valor de sus exportaciones representa el 92% del valor total de las actividades que realizó en dicho periodo. ¿Qué opción le otorga la Ley respecto del saldo?",
  o:["Únicamente compensarlo contra el mismo impuesto en los meses siguientes, porque la devolución sólo procede cuando la totalidad de sus actividades son exportaciones.",
     "Compensarlo o solicitar su devolución, porque sus exportaciones representan al menos el 90% del valor de sus actividades del mes.",
     "Acreditarlo contra el impuesto al valor agregado a su cargo.",
     "Ninguna, porque la tasa del 0% no genera saldos a favor."],
  a:1, why:"Si las exportaciones del art. 2, fr. III representan al menos el 90% del valor total de actividades del mes, el contribuyente puede compensar o solicitar la devolución.",
  hint:"El umbral es 90%." },

{ t:"pag", art:"Art. 5, párr. 6 LIEPS",
  q:"Un contribuyente determinó saldo a favor del impuesto en marzo. Tuvo impuesto a cargo de la misma categoría en marzo, abril y mayo, pero no compensó el saldo en ninguno de esos meses, pese a que pudo hacerlo. En junio pretende compensarlo íntegramente. ¿Qué consecuencia se produce?",
  o:["Puede compensarlo sin limitación, porque el saldo a favor no se extingue dentro del mismo ejercicio y sólo prescribe en el plazo general de cinco años.",
     "Pierde el derecho a compensarlo en los meses siguientes hasta por la cantidad en que pudo haberlo hecho.",
     "El saldo se convierte en una devolución automática a cargo de la autoridad.",
     "El saldo se acumula para efectos del impuesto sobre la renta."],
  a:1, why:"Si no compensa el saldo a favor en el mes de que se trate o en los dos siguientes, pudiendo haberlo hecho, pierde el derecho a hacerlo en los meses siguientes hasta por la cantidad en que pudo compensarlo.",
  hint:"Misma regla de \"mes + dos siguientes\" que el acreditamiento." },

{ t:"pag", art:"Art. 5 LIEPS",
  q:"Un contribuyente del impuesto por la enajenación de combustibles fósiles del inciso H) busca una alternativa al pago en efectivo, ya que participa en proyectos ambientales desarrollados en México que cuentan con aval internacional. ¿Qué mecanismo permite la Ley?",
  o:["Pagar mediante certificados de la Tesorería de la Federación.",
     "Pagar mediante bonos de carbono de proyectos desarrollados en México y avalados por la ONU, a su valor de mercado al momento del pago.",
     "Pagar en especie con los propios combustibles enajenados.",
     "Ninguno, porque el impuesto sólo puede cubrirse en efectivo o por transferencia electrónica, y cualquier otro instrumento requiere autorización especial."],
  a:1, why:"Para el inciso H), los contribuyentes pueden optar por pagar con bonos de carbono de proyectos desarrollados en México y avalados por la ONU, a su valor de mercado cuando se pague el impuesto.",
  hint:"Es un instrumento ambiental." },

{ t:"pag", art:"Art. 5, último párrafo LIEPS",
  q:"En el ejercicio de sus facultades de comprobación, la autoridad advierte que un contribuyente omitió el pago del impuesto por la enajenación de gasolina del inciso D). El contribuyente solicita que se disminuya el impuesto que le fue trasladado en sus adquisiciones. ¿Cómo debe determinarse el impuesto omitido?",
  o:["Aplicando las cuotas correspondientes y disminuyendo el impuesto trasladado en las adquisiciones.",
     "Aplicando las cuotas correspondientes, sin disminución alguna.",
     "Aplicando la tasa del 16% sobre la contraprestación cobrada.",
     "Aplicando las cuotas vigentes en el año en que se realiza la revisión."],
  a:1, why:"Cuando la autoridad advierta la omisión en el pago del IEPS del inciso D), aplicará las cuotas correspondientes sin disminución alguna.",
  hint:"La Ley lo castiga sin restar nada." },

{ t:"pag", art:"Art. 5o.-A LIEPS",
  q:"Un fabricante de bebidas alcohólicas enajena sus productos a través de un comisionista, al que paga su contraprestación por separado, sin incluirla en el valor de la enajenación. El comisionista sostiene que es él quien debe enterar directamente el impuesto que le corresponde. ¿Qué obligación tiene el fabricante?",
  o:["Ninguna, porque el comisionista es quien debe pagar su propio impuesto, al ser el prestador del servicio gravado.",
     "Retener el impuesto sobre la contraprestación que corresponda al comisionista y enterarlo, al no incluirse dicha contraprestación en el valor de la enajenación.",
     "Retener la totalidad del IVA trasladado por el comisionista, porque es la única retención prevista para estas operaciones.",
     "Trasladar al comisionista el impuesto que corresponde al bien enajenado."],
  a:1, why:"Fabricantes, productores, envasadores o importadores de bienes de los incisos A), B), C), F), I) y J) que vendan a través de comisionistas y similares deben retener el IEPS sobre la contraprestación de éstos. No retienen cuando la contraprestación se incluye en el valor de la enajenación.",
  hint:"Retención sobre la comisión." },

{ t:"pag", art:"Art. 5o.-A LIEPS",
  q:"Una persona física únicamente realiza actividades de comisión en la venta de tabacos labrados, y el productor le retiene el impuesto sobre su contraprestación. No realiza ninguna otra actividad gravada con el impuesto especial. ¿Tiene obligación de presentar declaraciones de pago mensual del impuesto?",
  o:["Sí, porque es contribuyente por la prestación de servicios gravados y la retención no lo libera de sus obligaciones formales mensuales.",
     "No, porque la Ley libera de esa obligación a quienes únicamente realicen dichas actividades y se les retenga el impuesto.",
     "Únicamente debe presentar una declaración anual informativa.",
     "Sí, cuando sus comisiones excedan de cierto monto anual."],
  a:1, why:"Quienes únicamente realicen esas actividades y se les retenga el impuesto no tienen obligación de presentar declaraciones de pago mensual.",
  hint:"La retención sustituye su pago." },

{ t:"pag", art:"Art. 5o.-A BIS LIEPS",
  q:"Una plataforma digital de intermediación cobra, por cuenta de un desarrollador residente en México, el precio y el impuesto por la descarga de videojuegos clasificados como violentos. El desarrollador no realiza otra actividad gravada con el impuesto. ¿Qué debe hacer la plataforma respecto del impuesto cobrado?",
  o:["Retener el 50% del impuesto cobrado y entregar el resto al desarrollador.",
     "Retener el 100% del impuesto cobrado, que el prestador del servicio considera como pago definitivo.",
     "No retener, porque el desarrollador es residente en territorio nacional y la retención sólo procede respecto de prestadores residentes en el extranjero.",
     "Retener el impuesto únicamente si el desarrollador lo solicita."],
  a:1, why:"Las plataformas que cobran el precio e IEPS por cuenta del prestador deben retener el 100% del IEPS cobrado; el retenedor sustituye al prestador en la obligación de pago y éste lo considera pago definitivo.",
  hint:"La retención es total." },

{ t:"pag", art:"Art. 5o.-B LIEPS",
  q:"Una sociedad que realiza juegos con apuestas pagó en el mes la participación al Gobierno Federal prevista en la legislación de la materia, así como un impuesto estatal sobre juegos con apuestas. Pretende disminuir ambos importes del impuesto a su cargo por esas actividades. ¿Qué procede?",
  o:["No puede disminuir ninguno, porque ambos conceptos son gastos deducibles para el ISR y la Ley no permite su disminución del impuesto especial a cargo.",
     "Disminuye la participación federal pagada y el impuesto estatal efectivamente pagado, éste sin exceder de la quinta parte del impuesto de esas actividades.",
     "Disminuye ambos montos sin limitación alguna.",
     "Únicamente disminuye el impuesto estatal, sin limitación alguna."],
  a:1, why:"Puede disminuir la participación al Gobierno Federal pagada en el mismo mes (el exceso en meses siguientes, sin acreditamiento, compensación ni devolución) y el impuesto estatal sobre juegos efectivamente pagado, sin exceder de la quinta parte del IEPS.",
  hint:"Quinta parte = 20%." },

{ t:"pag", art:"Art. 5o.-C LIEPS y art. 1o.-B LIVA",
  q:"Un productor de bebidas recibe el 29 de septiembre un cheque como pago de una enajenación gravada. Lo deposita ese mismo día, pero el banco lo cobra efectivamente el 2 de octubre. El cheque no fue transmitido a terceros. Para efectos de la Ley del IEPS, ¿cuándo se considera efectivamente cobrada la contraprestación?",
  o:["El 29 de septiembre, porque la entrega del cheque satisface fiscalmente la contraprestación.",
     "El 2 de octubre, porque la LIEPS remite a los supuestos de cobro efectivo de la LIVA y en esa fecha se realiza el cobro del cheque.",
     "En ambos meses, distribuyendo proporcionalmente el cobro entre la fecha de recepción del cheque y la de su liquidación bancaria.",
     "El 29 de septiembre, porque el depósito bancario realizado ese mismo día equivale al cobro efectivo del documento recibido."],
  a:1, why:"El art. 5o.-C remite a la LIVA para determinar cuándo se cobran efectivamente las contraprestaciones. En pagos con cheque, se considera cobrado en la fecha de cobro del mismo.",
  hint:"La LIEPS no define el cobro efectivo por sí sola; remite a otra ley." },

{ t:"pag", art:"Art. 6 LIEPS",
  q:"Un fabricante recibe la devolución de bebidas por las que ya había pagado el impuesto. En la declaración siguiente, el impuesto causado es inferior al que debe disminuir con motivo de la devolución. La operación original no estuvo sujeta a retención. ¿Qué procede?",
  o:["Pierde la diferencia que no alcanzó a disminuir en la declaración siguiente, porque la disminución sólo procede en un único periodo.",
     "Disminuye en la siguiente declaración y, si no alcanza, la diferencia en la siguiente o siguientes declaraciones hasta agotarla.",
     "Solicita la devolución inmediata de la diferencia no disminuida.",
     "Corrige la declaración del mes en que realizó la enajenación original, porque la devolución modifica retroactivamente el impuesto causado."],
  a:1, why:"El contribuyente disminuirá en la siguiente declaración el impuesto de la devolución, descuento o bonificación; si es inferior, la diferencia en la siguiente o siguientes declaraciones hasta agotarla.",
  hint:"Similar al tratamiento de IVA, pero en declaraciones siguientes." },

{ t:"pag", art:"Art. 6, párr. 3 LIEPS",
  q:"Un distribuidor devuelve mercancía a su proveedor, quien le había trasladado el impuesto en forma expresa y por separado, y dicho impuesto ya había sido acreditado. En el mes de la devolución, el impuesto acreditable disponible es inferior al impuesto que debe disminuir. La operación original no estuvo sujeta a retención. ¿Qué procede?",
  o:["Conservar el acreditamiento original y reconocer la restitución como ingreso del mes.",
     "Disminuir el impuesto acreditable hasta su monto y pagar la diferencia en la declaración del mes al que corresponda la devolución.",
     "Disminuir únicamente el acreditamiento disponible y trasladar el excedente al ejercicio siguiente, al no existir impuesto acreditable suficiente en el mes.",
     "Corregir exclusivamente la declaración original y mantener sin cambios la del mes de la devolución."],
  a:1, why:"El adquirente disminuye del impuesto acreditable del mes el impuesto de la devolución; si el acreditable es inferior, paga la diferencia en la declaración del mes al que corresponda la devolución.",
  hint:"El adquirente no puede quedarse con un beneficio que ya no tiene." }
);
